def flow_adjusted_return(snapshots, flows):
    """Chain valued subperiods; deposits are removed at their recorded boundary.

    The engine records a valuation immediately before and after each funding.
    Old data without those valuations has an explicit timing limitation.
    """
    if len(snapshots) < 2:
        return None
    growth = Decimal(1)
    for prior, current in zip(snapshots, snapshots[1:]):
        if prior["equity_cents"] <= 0 or current["missing_marks"] or current.get("stale_marks") != 0:
            return None
        amount = sum((Decimal(f["amount_cents"]) for f in flows if prior["timestamp"] < f["timestamp"] <= current["timestamp"]), Decimal(0))
        growth *= (Decimal(current["equity_cents"]) - amount) / Decimal(prior["equity_cents"])

